const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Depok region
  const depokCoords = ee.Geometry.Point([106.8, -6.4]);
  const depokBuffer = depokCoords.buffer(15000); // 15 km buffer

  // 1990: Landsat 5 TM
  const col1990 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(depokBuffer)
    .filterDate('1990-01-01', '1990-12-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 50));

  const size1990 = col1990.size().getInfo();
  console.log(`1990 Images: ${size1990}`);

  if (size1990 === 0) {
    console.log('No data for 1990.');
    console.log('C1');
    return;
  }

  // 2019: Landsat 8 OLI
  const col2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(depokBuffer)
    .filterDate('2019-01-01', '2019-12-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 50));

  const size2019 = col2019.size().getInfo();
  console.log(`2019 Images: ${size2019}`);

  if (size2019 === 0) {
    console.log('No data for 2019.');
    console.log('C1');
    return;
  }

  // Function to calculate NDVI
  const calcNDVI = (col, suffix) => {
    const ndviCol = col.map(img => {
      const ndvi = img.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
      const mask = img.select('QA_PIXEL').bitwiseAnd(1).eq(0); // Clear pixels
      return ndvi.updateMask(mask);
    });

    const meanNDVI = ndviCol.mean();
    const count = meanNDVI.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: depokBuffer,
      scale: 3000,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    const ndviVal = meanNDVI.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: depokBuffer,
      scale: 3000,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    console.log(`${suffix} - NDVI: ${(ndviVal || 'null').toFixed(3)}, Pixels: ${count || 0}`);
    return { ndvi: ndviVal, count: count };
  };

  const result1990 = calcNDVI(col1990, '1990');
  const result2019 = calcNDVI(col2019, '2019');

  // Validation
  if (result1990.count === 0 || result2019.count === 0) {
    console.log('No valid pixels after masking.');
    console.log('C2');
    return;
  }

  if (result1990.ndvi === null || result2019.ndvi === null || 
      isNaN(result1990.ndvi) || isNaN(result2019.ndvi)) {
    console.log('Calculation failed - invalid NDVI.');
    console.log('C3');
    return;
  }

  if (result1990.ndvi < -1 || result1990.ndvi > 1 || 
      result2019.ndvi < -1 || result2019.ndvi > 1) {
    console.log('Invalid NDVI range.');
    console.log('C3');
    return;
  }

  // Compare: Was 2019 lower than 1990?
  const isLower = result2019.ndvi < result1990.ndvi;
  console.log(`Comparison: 2019 (${result2019.ndvi.toFixed(3)}) < 1990 (${result1990.ndvi.toFixed(3)})? ${isLower}`);

  if (isLower) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
